#include <bits/stdc++.h>
#define int long long
using namespace std;
int n,m,a[500005];
signed main(){
	freopen("crystal.in","r",stdin);
	freopen("crystal.out","w",stdout);
	scanf("%lld%lld",&n,&m);
	for(int i=1;i<=n;++i) scanf("%lld",&a[i]);
	stable_sort(a+1,a+n+1);
	int sum=0,cnt=0;
	int ans=0;
	for(int i=1;i<=n;++i){
		sum+=a[i];
		cnt+=1;
		while(a[i]*cnt-sum>m){
			sum-=a[i-cnt+1];
			--cnt;
		}
		ans=max(ans,cnt);
	}
	printf("%lld\n",ans);
	return 0;
}
